-- ── hand-written: a rate must suit its category ─────────────────────────────────────────────────
-- Exempt goods carry no tax at all. Zero-rated goods are taxed at 0 but can still carry further
-- tax (Sales Tax Act 1990, s.4 applies "except" s.3(1A)). Every other kind of category exists to
-- charge some tax. The app checks this first (tax/rules.ts); the database refuses it whoever
-- writes the row.
CREATE FUNCTION app.check_tax_rate_for_kind() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_kind public.tax_category_kind;
BEGIN
  SELECT c.kind INTO v_kind FROM public.tax_categories c
    WHERE c.tenant_id = NEW.tenant_id AND c.id = NEW.category_id;
  IF v_kind = 'exempt' AND (NEW.rate <> 0 OR NEW.further_tax_rate <> 0) THEN
    RAISE EXCEPTION 'an exempt category carries no tax' USING ERRCODE = 'check_violation';
  END IF;
  IF v_kind = 'zero_rated' AND NEW.rate <> 0 THEN
    RAISE EXCEPTION 'a zero-rated category is taxed at zero' USING ERRCODE = 'check_violation';
  END IF;
  IF v_kind NOT IN ('exempt', 'zero_rated') AND NEW.rate = 0 THEN
    RAISE EXCEPTION 'a taxed category needs a rate above zero' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_tax_rate_for_kind() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER tax_rates_check_kind
  BEFORE INSERT OR UPDATE ON public.tax_rates
  FOR EACH ROW EXECUTE FUNCTION app.check_tax_rate_for_kind();
--> statement-breakpoint

-- ── hand-written: every company's starting rows ─────────────────────────────────────────────────
-- The FY 2026-27 values (tax year 2027), each effective from 1 July 2026, read from FBR's texts
-- of the Sales Tax Act 1990 and the Income Tax Ordinance 2001 as amended to 30 June 2026 and from
-- each province's own Act. docs/RATES-REVIEW.md lists every value with its source for the
-- accountant's sign-off. A change in the law is a new dated row, never an edit of these.
-- Running this twice for a company adds nothing.
CREATE FUNCTION app.seed_tax_defaults(p_tenant uuid, p_user uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  c_from CONSTANT date := DATE '2026-07-01';
BEGIN
  INSERT INTO public.tax_categories (tenant_id, name, kind, created_by) VALUES
    (p_tenant, 'Standard rate', 'standard', p_user),
    (p_tenant, 'Third Schedule (retail price)', 'third_schedule', p_user),
    (p_tenant, 'Zero-rated', 'zero_rated', p_user),
    (p_tenant, 'Exempt', 'exempt', p_user)
  ON CONFLICT DO NOTHING;

  INSERT INTO public.tax_rates
    (tenant_id, category_id, effective_from, rate, further_tax_rate, legal_reference, created_by, updated_by)
  SELECT p_tenant, c.id, c_from, v.rate, v.further_tax_rate, v.legal_reference, p_user, p_user
  FROM (VALUES
    ('Standard rate', 18, 4, 'Sales Tax Act 1990, s.3(1); further tax s.3(1A)'),
    ('Third Schedule (retail price)', 18, 0, 'Sales Tax Act 1990, s.3(2)(a) and Third Schedule; no further tax under SRO 648(I)/2013'),
    ('Zero-rated', 0, 0, 'Sales Tax Act 1990, s.4 and Fifth Schedule'),
    ('Exempt', 0, 0, 'Sales Tax Act 1990, s.13 and Sixth Schedule')
  ) AS v (name, rate, further_tax_rate, legal_reference)
  JOIN public.tax_categories c ON c.tenant_id = p_tenant AND c.name = v.name
  ON CONFLICT DO NOTHING;

  INSERT INTO public.withholding_rules
    (tenant_id, kind, code, label, effective_from, base, rate, rate_non_atl, legal_reference, created_by, updated_by)
  SELECT p_tenant, v.kind::public.withholding_kind, v.code, v.label, c_from, v.base::public.withholding_base,
         v.rate, v.rate_non_atl, v.legal_reference, p_user, p_user
  FROM (VALUES
    ('income_tax', 'income_tax.goods.company', 'Goods, from a company', 'gross_amount', 5, 10, 'Income Tax Ordinance 2001, s.153(1)(a); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.goods.non_company', 'Goods, from an individual or AOP', 'gross_amount', 5.5, 11, 'Income Tax Ordinance 2001, s.153(1)(a); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.goods.rice_oils', 'Goods: rice, cotton seed oil or edible oils', 'gross_amount', 1.5, 3, 'Income Tax Ordinance 2001, s.153(1)(a); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.toll_manufacturing.company', 'Toll manufacturing, by a company', 'gross_amount', 9, 18, 'Income Tax Ordinance 2001, s.153(1)(a); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.toll_manufacturing.non_company', 'Toll manufacturing, by an individual or AOP', 'gross_amount', 11, 22, 'Income Tax Ordinance 2001, s.153(1)(a); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.services.listed', 'Services: listed sectors such as transport, freight forwarding, courier, security guards and warehousing', 'gross_amount', 7, 14, 'Income Tax Ordinance 2001, s.153(1)(b); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.services.it', 'Services: IT and IT-enabled services', 'gross_amount', 4, 8, 'Income Tax Ordinance 2001, s.153(1)(b); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.services.professional', 'Services: independent professionals such as doctors, lawyers, architects and accountants', 'gross_amount', 15, 30, 'Income Tax Ordinance 2001, s.153(1)(b); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.services.media_advertising', 'Services: advertising in electronic and print media', 'gross_amount', 1.5, 3, 'Income Tax Ordinance 2001, s.153(1)(b); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.services.port_terminal', 'Services: terminal and port operating companies', 'gross_amount', 12, 24, 'Income Tax Ordinance 2001, s.153(1)(b); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.services.other', 'Services: any other service', 'gross_amount', 14, 28, 'Income Tax Ordinance 2001, s.153(1)(b); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.contracts.company', 'Contracts, with a company', 'gross_amount', 7.5, 15, 'Income Tax Ordinance 2001, s.153(1)(c); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.contracts.non_company', 'Contracts, with an individual or AOP', 'gross_amount', 8, 16, 'Income Tax Ordinance 2001, s.153(1)(c); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('income_tax', 'income_tax.contracts.sportsperson', 'Contracts, with a sportsperson', 'gross_amount', 15, 30, 'Income Tax Ordinance 2001, s.153(1)(c); First Schedule, Part III, Division III; Tenth Schedule, rule 1'),
    ('sales_tax', 'sales_tax.active_taxpayer', 'Supplier is an active taxpayer (deducted by a company)', 'sales_tax', 20, NULL, 'Sales Tax Act 1990, s.3(7); Eleventh Schedule, serial 1'),
    ('sales_tax', 'sales_tax.active_distributor', 'Supplier is an active taxpayer registered as a wholesaler, dealer or distributor (deducted by a company)', 'sales_tax', 10, NULL, 'Sales Tax Act 1990, s.3(7); Eleventh Schedule, serial 2'),
    ('sales_tax', 'sales_tax.not_active_taxpayer', 'Supplier is not an active taxpayer', 'gross_amount', 5, NULL, 'Sales Tax Act 1990, s.3(7); Eleventh Schedule, serial 4'),
    ('sales_tax', 'sales_tax.advertisement', 'Advertisement services (deducted by a registered person)', 'sales_tax', 100, NULL, 'Sales Tax Act 1990, s.3(7); Eleventh Schedule, serial 5'),
    ('provincial_sales_tax', 'provincial_sales_tax.punjab', 'Punjab: standard rate on services', 'taxable_value', 16, NULL, 'Punjab Sales Tax on Services Act 2012, s.2(41A) and s.10'),
    ('provincial_sales_tax', 'provincial_sales_tax.sindh', 'Sindh: standard rate on services', 'taxable_value', 15, NULL, 'Sindh Sales Tax on Services Act 2011, s.8(1)'),
    ('provincial_sales_tax', 'provincial_sales_tax.khyber_pakhtunkhwa', 'Khyber Pakhtunkhwa: standard rate on services', 'taxable_value', 15, NULL, 'Khyber Pakhtunkhwa Sales Tax on Services Act 2022'),
    ('provincial_sales_tax', 'provincial_sales_tax.balochistan', 'Balochistan: standard rate on services', 'taxable_value', 15, NULL, 'Balochistan Sales Tax on Services Act 2015, s.10(1)')
  ) AS v (kind, code, label, base, rate, rate_non_atl, legal_reference)
  ON CONFLICT DO NOTHING;
END $$;
--> statement-breakpoint
-- Not for the app to call: it writes into whichever company it is given. Only app.create_tenant
-- (below) and migrations run it.
REVOKE ALL ON FUNCTION app.seed_tax_defaults(uuid, uuid) FROM PUBLIC;
