-- A new company gets its tax rows in the same transaction that creates it. The body is
-- 0000_tenancy.sql's with one line added; privileges on the function carry over.
CREATE OR REPLACE FUNCTION app.create_tenant(p_name text, p_email text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_user uuid := app.current_user_id();
  v_tenant uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'app.user_id is not set' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO public.tenants (name, created_by)
    VALUES (btrim(p_name), v_user)
    RETURNING id INTO v_tenant;
  INSERT INTO public.memberships (tenant_id, user_id, email, role, created_by)
    VALUES (v_tenant, v_user, lower(btrim(p_email)), 'owner', v_user);
  PERFORM app.seed_tax_defaults(v_tenant, v_user);
  RETURN v_tenant;
END $$;
--> statement-breakpoint

-- Companies that already exist get the same starting rows.
SELECT app.seed_tax_defaults(t.id, t.created_by) FROM public.tenants t;
